using System;
using System.Linq;
using BlockLogger.Frontend;
using NewfiesCommunityMOTD;
using NewfiesSailing;
using NewfiesServerEssentials.Discord.Integration;
int checks = 0;
void Check(bool value, string message) { checks++; if (!value) throw new Exception(message); }
var names = AdminPlayerChoices.Create(new[] { ("account-2", "Lorreth"), ("account-1", "Lorreth"), ("account-1", "Other"), ("", "bad") });
Check(names.Values.SequenceEqual(new[]{"account-1", "account-2"}), "Actions use distinct UIDs even when roleplay names match");
Check(names.Labels.Distinct().Count() == 2, "Duplicate display names remain distinguishable");
Check(names.Values.All(x => x != "Lorreth"), "Display aliases never become action targets");
Check(AdminPlayerChoices.Create(Array.Empty<(string,string)>()).Values.Single() == "", "Empty picker sentinel");
Check(AdminPlayerChoices.Create(new[]{("uid", "")}).Labels.Single() == "uid", "Empty display-name fallback");
var renamed = AdminPlayerChoices.Create(new[]{("account-1", "New RP name")});
Check(renamed.Values.Single() == "account-1", "Renaming does not change target identity");
string local = "<font size=\"17\"><strong>Owner title</strong></font>\r\nOwner text[br]- Item";
var item = new MotdFeedItem { Id="discord-123", Title="<unsafe> & title", Author="<author>", BodyVtml="<strong>Kept markup</strong>\r\nNext line", UnixTime=1704067200, Url="https://discord.com/channels/a?x=1&y=2", Important=true };
string Build(string? l, bool use=true, int limit=10, string accent="#D9B777", bool merge=true) => MotdFeedFormatter.Build("Updates", l, use, new[]{item}, limit, accent, merge);
var feed=Build(local);
Check(feed.Contains("Owner title") && !feed.Contains("Server Update"), "Do not duplicate owner headings");
Check(feed.Contains("&lt;unsafe&gt; & title"), "Remote titles are escaped without literal entities");
Check(feed.Contains("&lt;author&gt;"), "Remote authors are escaped");
Check(feed.Contains("<strong>Kept markup</strong>"), "Body VTML is preserved");
Check(feed.Contains("[[MOTDNEW:discord-123]]"), "Unread IDs survive formatting");
Check(feed.Contains("IMPORTANT"), "Important marker survives");
Check(feed.Contains("01 Jan 2024") && feed.Contains("UTC"), "Dates carry explicit timezone");
Check(!feed.Contains('\r') && !feed.Contains("[br]"), "All line endings normalize");
Check(Build(local,merge:false).Contains("Kept markup") && !Build(local,merge:false).Contains("Owner title"), "Remote replacement honors merge setting");
Check(Build(local,use:false,merge:false).Contains("Owner title"), "Local fallback when remote feed is disabled");
Check(!Build(null,use:false).Contains("[[MOTDNEW:"), "Disabled remote has no unread markers");
Check(Build(null,use:false).Contains("No updates"), "Empty feed has useful text");
Check(!Build(null,accent:"red\" size=\"999").Contains("999"), "Invalid accent cannot inject VTML");
item.Url="javascript:alert(1)";
Check(!Build(null).Contains("href="), "Unsafe URL scheme is rejected");
item.UnixTime=long.MaxValue;
Check(Build(null).Contains("Kept markup"), "Invalid date does not hide a post");
var many = Enumerable.Range(0,70).Select(i => new MotdFeedItem{Title="p"+i,Id="id-"+i}).ToArray();
var limited = MotdFeedFormatter.Build("News",null,true,many,999,null,true);
Check(limited.Contains("[[MOTDNEW:id-49]]") && !limited.Contains("[[MOTDNEW:id-50]]"), "Hard feed-item cap retained");
string Md(string md) => DiscordMarkdown.ToVtml(md, (kind, id) => kind == '@' && id == 123 ? "Newfie" : null);
Check(Md("**bold** *it* _it2_ ***both***") == "<strong>bold</strong> <i>it</i> <i>it2</i> <strong><i>both</i></strong>", "Discord emphasis becomes VTML");
Check(Md("# Big news") == "<font size=\"20\"><strong>Big news</strong></font>", "Discord headings become sized bold text");
Check(Md("- one\n  - two").Contains("  • one\n      • two"), "Discord lists become nested bullets");
Check(Md("Hi <@123> <@!9> <#5> <:pepe:77>").Contains("@Newfie") && Md("<@!9>").Contains("@user") && Md("<#5>").Contains("#channel") && Md("<:pepe:77>") == ":pepe:", "Mentions and custom emoji never show raw IDs");
Check(Md("<t:1704067200:F>") == "01 Jan 2024 · 00:00 UTC" && Md("<t:1704067200:d>") == "01 Jan 2024", "Discord timestamps render as dates");
Check(Md("[site](https://example.com/a?b=1&c=2)") == "<a href=\"https://example.com/a?b=1&c=2\">site</a>", "Masked links become VTML links");
Check(Md("see https://example.com/x.").EndsWith("</a>.") && Md("<https://example.com>").Contains("href="), "Bare and suppressed URLs become links");
Check(Md("[x](javascript:alert(1))").IndexOf("href=", StringComparison.Ordinal) < 0, "Unsafe link schemes stay text");
Check(Md("```\n**raw** <b>\n```") == "<font color=\"#E6C07B\">    **raw** &lt;b&gt;</font>", "Code blocks keep raw text and escape markup");
Check(Md("`a*b*c`") == "<font color=\"#E6C07B\">a*b*c</font>", "Inline code skips emphasis");
Check(Md("<strong>x</strong> & it's") == "&lt;strong&gt;x&lt;/strong&gt; & it's", "Discord text cannot inject VTML and keeps punctuation literal");
Check(Md("snake_case_name 2*3*4 \\*lit\\*") == "snake_case_name 2*3*4 *lit*", "Intraword markers and escapes stay literal");
Check(Md("> quoted").Contains("│ quoted") && Md("-# tiny").Contains("size=\"12\""), "Quotes and subtext are styled");
Check(Md("~~old~~ ||spoiler||").IndexOf('~') < 0 && Md("||spoiler||").IndexOf('|') < 0, "Strike and spoiler markers are removed");
Check(DiscordMarkdown.ToPlainText("# **Big** news for <@123>", (k, id) => "Newfie") == "Big news for @Newfie", "Titles are plain text");
Check(Md("🎉 Big **news** 🎉🎉!") == "Big <strong>news</strong> !", "Decorative emoji are removed instead of drawing squares");
Check(Md("✅ done ❌ failed ⚠️ careful ⭐ star 1️⃣ one ➡️ next") == "[+] done [x] failed [!] careful star 1 one -&gt; next", "Status emoji become readable symbols");
Check(Md("👨‍👩‍👧 family 👍🏽 ok 🇨🇦 flag") == "family ok flag", "Joined, skin-tone and flag emoji leave no fragments");
Check(Md("- 🔥 hot item") == "  • hot item" && DiscordMarkdown.ToPlainText("📢 Server Update") == "Server Update", "Leading emoji do not leave stray spaces");
Check(Md("café → naïve “quotes” — ok") == "café → naïve “quotes” — ok", "Normal accented text and punctuation are kept");
Check(SailingModel.Beaufort(0) == 0 && SailingModel.Beaufort(17) == 5 && SailingModel.Beaufort(100) == 12, "Beaufort thresholds");
Check(Math.Abs(SailingModel.WindFromBearing(0, 1) - 0) < 1e-6 && Math.Abs(SailingModel.WindFromBearing(1, 0) - 270) < 1e-6, "Wind blowing south comes from north; blowing east comes from west");
Check(SailingModel.Compass(359) == "N" && SailingModel.Compass(90) == "E", "Compass names");
Check(Math.Abs(SailingModel.AngleOffWind(0, 1, 0, 1) - 180) < 1e-6 && Math.Abs(SailingModel.AngleOffWind(0, -1, 0, 1)) < 1e-6 && Math.Abs(SailingModel.AngleOffWind(1, 0, 0, 1) - 90) < 1e-6, "Running is 180, head to wind is 0, beam is 90");
Check(SailingModel.PointOfSailEfficiency(0) == 0 && SailingModel.PointOfSailEfficiency(90) == 1, "Irons gives no drive, beam reach is best");
Check(SailingModel.PointOfSailEfficiency(180) < SailingModel.PointOfSailEfficiency(120) && SailingModel.PointOfSailEfficiency(30) < SailingModel.PointOfSailEfficiency(60), "Polar shape");
Check(SailingModel.SpeedMultiplier(0, 90, 0.35, 1.35, 17, 41) == 0.35, "Becalmed boats crawl");
Check(SailingModel.SpeedMultiplier(17, 90, 0.35, 1.35, 17, 41) > SailingModel.SpeedMultiplier(17, 10, 0.35, 1.35, 17, 41), "Beam reach beats head to wind");
Check(SailingModel.SpeedMultiplier(70, 90, 0.35, 1.35, 17, 41) < SailingModel.SpeedMultiplier(30, 90, 0.35, 1.35, 17, 41), "Storms slow boats");
Check(Enumerable.Range(0, 500).All(i => SailingModel.Gust(i * 0.3, 0.35) >= 0), "Gusts stay non-negative");
Check(Enumerable.Range(0, 400).All(i => { var (p, r) = SailingModel.Bob(i * 0.25, 12); return Math.Abs(r) <= 0.38 && Math.Abs(p) <= 0.38; }), "Bobbing stays within bounds");
Check(Math.Abs(SailingModel.Bob(5, 9).Roll) < 1 && Enumerable.Range(0, 200).Max(i => Math.Abs(SailingModel.Bob(i * 0.2, 9).Roll)) > Enumerable.Range(0, 200).Max(i => Math.Abs(SailingModel.Bob(i * 0.2, 2).Roll)), "Rougher seas roll harder");
Check(SailingModel.SplashCount(2, 0.2) == 0 && SailingModel.SplashCount(9, 0.2) > SailingModel.SplashCount(4, 0.2) && SailingModel.SplashCount(12, 1) <= 40, "Splash scales with force and is capped");
Check(SailingModel.SailArea(SailTrim.Furled) < SailingModel.SailArea(SailTrim.Reefed) && SailingModel.SailArea(SailTrim.Reefed) < SailingModel.SailArea(SailTrim.Full), "Trim areas ordered");
Check(SailingModel.TryParseTrim("Reef", out var tr) && tr == SailTrim.Reefed && !SailingModel.TryParseTrim("bogus", out _), "Trim parsing");
Check(SailingModel.SpeedMultiplier(45, 90, 0.35, 1.35, 17, 25, 0.55) > SailingModel.SpeedMultiplier(45, 90, 0.35, 1.35, 17, 25, 1.0), "Reefing is faster than full sail in a gale");
Check(SailingModel.SpeedMultiplier(12, 90, 0.35, 1.35, 17, 25, 1.0) > SailingModel.SpeedMultiplier(12, 90, 0.35, 1.35, 17, 25, 0.55), "Full sail is faster in moderate wind");
Check(SailingModel.SpeedMultiplier(20, 90, 0.35, 1.35, 17, 25, 0.05) < 0.3, "Furled sails lose way");
Check(SailingModel.Overpowered(30, 1, 25) && !SailingModel.Overpowered(30, 0.55, 25), "Overpowered only under full sail");
Check(SailingModel.Heel(25, 90, 1, 17) > SailingModel.Heel(25, 90, 0.55, 17) && SailingModel.Heel(25, 0, 1, 17) < 1e-9 && SailingModel.Heel(25, 180, 1, 17) < 1e-6, "Heel peaks on a beam reach under full sail");
Check(SailingModel.WindSide(0, -1, 1, 0) != 0 && SailingModel.WindSide(0, -1, 1, 0) == -SailingModel.WindSide(0, -1, -1, 0), "Wind side flips with the wind");
Check(SailingModel.LeewayFraction(40, 1, 1) > SailingModel.LeewayFraction(120, 1, 1) && SailingModel.LeewayFraction(180, 1, 1) == 0, "Leeway greatest close-hauled, nil running");
Check(SailingModel.SquallFactor(-1, 60, 2) == 1 && SailingModel.SquallFactor(60, 60, 2) == 1 && Math.Abs(SailingModel.SquallFactor(30, 60, 2) - 2) < 1e-9 && SailingModel.SquallFactor(5, 60, 2) < 2, "Squall ramps to the peak and ends");
Check(SailingModel.SailArea(SailTrim.Furled) < SailingModel.SailArea(SailTrim.Reefed) && SailingModel.SailArea(SailTrim.Reefed) < SailingModel.SailArea(SailTrim.Full), "Trim areas ordered");
Check(SailingModel.TryParseTrim("Reef", out var tr) && tr == SailTrim.Reefed && !SailingModel.TryParseTrim("bogus", out _), "Trim parsing");
Check(SailingModel.SpeedMultiplier(45, 90, 0.35, 1.35, 17, 25, 0.55) > SailingModel.SpeedMultiplier(45, 90, 0.35, 1.35, 17, 25, 1.0), "Reefing is faster than full sail in a gale");
Check(SailingModel.SpeedMultiplier(12, 90, 0.35, 1.35, 17, 25, 1.0) > SailingModel.SpeedMultiplier(12, 90, 0.35, 1.35, 17, 25, 0.55), "Full sail is faster in moderate wind");
Check(SailingModel.SpeedMultiplier(20, 90, 0.35, 1.35, 17, 25, 0.05) < 0.3, "Furled sails lose way");
Check(SailingModel.Overpowered(30, 1, 25) && !SailingModel.Overpowered(30, 0.55, 25), "Overpowered only under full sail");
Check(SailingModel.Heel(25, 90, 1, 17) > SailingModel.Heel(25, 90, 0.55, 17) && SailingModel.Heel(25, 0, 1, 17) < 1e-9 && SailingModel.Heel(25, 180, 1, 17) < 1e-6, "Heel peaks on a beam reach under full sail");
Check(SailingModel.WindSide(0, -1, 1, 0) != 0 && SailingModel.WindSide(0, -1, 1, 0) == -SailingModel.WindSide(0, -1, -1, 0), "Wind side flips with the wind");
Check(SailingModel.LeewayFraction(40, 1, 1) > SailingModel.LeewayFraction(120, 1, 1) && SailingModel.LeewayFraction(180, 1, 1) == 0, "Leeway greatest close-hauled, nil running");
Check(SailingModel.SquallFactor(-1, 60, 2) == 1 && SailingModel.SquallFactor(60, 60, 2) == 1 && Math.Abs(SailingModel.SquallFactor(30, 60, 2) - 2) < 1e-9 && SailingModel.SquallFactor(5, 60, 2) < 2, "Squall ramps to the peak and ends");
Check(Math.Abs(SailingModel.TemporalWindRotation(123.4)) <= 1.5 && Enumerable.Range(0, 300).Select(i => SailingModel.TemporalWindRotation(i)).Max() > 0.5, "Storm wind rotation is bounded but wanders");
var rotated = SailingModel.RotateWind(1, 0, Math.PI / 2);
Check(Math.Abs(rotated.X) < 1e-9 && Math.Abs(rotated.Z - 1) < 1e-9, "Wind rotation preserves length and turns the vector");
Check(Enumerable.Range(0, 200).All(i => Math.Abs(SailingModel.CompassNoise(i * 0.37)) <= 40) && SailingModel.StormForce(11, true) == 12 && SailingModel.StormForce(4, true) == 6 && SailingModel.StormForce(4, false) == 4, "Compass noise bounded; storm force boost clamped");
Check(SailingModel.AnchorDrag(20, 35) == 0 && SailingModel.AnchorDrag(70, 35) == 1 && SailingModel.AnchorDrag(50, 35) > 0, "Anchor holds in moderate wind, drags in a gale");
Check(SailingModel.Barometer(null, false, false, 0) > 1010 && SailingModel.Barometer(30, false, false, 0) < SailingModel.Barometer(170, false, false, 0) && SailingModel.Barometer(null, true, false, 0) < 990, "Glass falls before and during a squall");
Check(SailingModel.Trend(1013, 1005) == "falling rapidly" && SailingModel.Trend(1013, 1013.2) == "steady" && SailingModel.GlassForecast(985) == "storm conditions" && SailingModel.GlassForecast(1013) == "fair", "Trend and forecast text");
Check(SailingModel.WakeCount(0) == 0 && SailingModel.WakeCount(0.2) > SailingModel.WakeCount(0.02) && SailingModel.WakeCount(5) <= 14, "Wake scales with speed and is capped");
Console.WriteLine($"{checks} checks passed");
